  --espace: 16px;
  display: grid;
  gap: var(--espace);
  padding: var(--espace);
}
.entete h1 {
  margin: 0;
  font-size: clamp(1.5rem, 1rem + 2.5vw, 2.5rem);
  line-height: 1.2;
}
.nav {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.nav a {
  display: block;
  padding: 12px 16px;
}
.cartes {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: var(--espace);
}
.carte {
  min-width: 0;
  overflow-wrap: anywhere;
}
@media (min-width: 600px) {
  .entete {
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
